# Importação de CSV

## O quê e por quê

Digitar transações uma a uma não escala. Bancos permitem baixar o extrato em CSV, então o app importa esse arquivo, mostra uma prévia e só grava o que o usuário confirmar. Tudo é processado no navegador; o arquivo nunca sai da máquina.

Fluxo: escolher arquivo, escolher conta de destino, mapear colunas, revisar prévia (com categorias e duplicatas), confirmar.

## Critérios de aceitação

1. O usuário seleciona um arquivo `.csv` pelo seletor ou arrastando-o; arquivos de outro tipo ou acima de 5 MB são recusados com mensagem clara.
2. O parser detecta o separador (`,` ou `;`) e lida com campos entre aspas, aspas escapadas e quebras de linha dentro de campo; a codificação UTF-8 e Windows-1252 é tratada de forma que acentos apareçam corretamente.
3. O usuário mapeia as colunas do arquivo para data, descrição e valor; também é aceito o formato com colunas separadas de crédito e débito. O mapeamento usado é lembrado para a próxima importação na mesma conta.
4. O formato de data é reconhecido entre `dd/mm/aaaa`, `aaaa-mm-dd` e `dd-mm-aaaa`; o usuário pode corrigir a escolha, e uma data ambígua ou inválida marca a linha com erro em vez de adivinhar.
5. Valores em formato brasileiro (`1.234,56`) e internacional (`1234.56`) são convertidos para centavos; o sinal negativo, parênteses ou a coluna de débito definem a despesa, e a ausência deles define a receita.
6. A prévia exibe todas as linhas com data, descrição, valor, tipo e categoria sugerida, e destaca linhas com erro e linhas suspeitas de duplicata; o contador mostra quantas serão importadas, ignoradas e com erro.
7. Uma linha é considerada duplicata quando já existe transação na mesma conta com mesma data, mesmo valor e mesma descrição normalizada (sem acentos, caixa e espaços extras); duplicatas vêm desmarcadas por padrão, mas o usuário pode marcá-las.
8. A categoria sugerida vem de regras simples: se uma descrição normalizada igual já foi categorizada antes, reutiliza essa categoria; caso contrário, usa "Outros" do tipo correspondente. O usuário pode trocar a categoria de cada linha antes de confirmar.
9. Linhas com erro não são importadas e ficam listadas com o motivo (data inválida, valor ausente); o usuário pode importar as demais.
10. Ao confirmar, todas as linhas marcadas são gravadas de uma só vez: se a gravação falhar (por exemplo, limite do localStorage), nada é gravado e o usuário vê o erro.
11. Após a importação, o app mostra um resumo (importadas, ignoradas, com erro) e oferece desfazer a importação inteira, que remove exatamente as transações criadas por ela.
12. Importar o mesmo arquivo duas vezes seguidas não cria transações duplicadas com as opções padrão.

## Fora do escopo

- Formatos OFX, QIF, PDF e planilhas XLSX.
- Download automático de extratos e integração com bancos.
- Importação de contas, categorias, orçamentos ou metas por CSV.
- Aprendizado de máquina ou serviço externo para categorização.
- Importação de transações parceladas ou de múltiplas contas em um só arquivo.
- Exportação de transações em CSV (pode virar spec própria).
import { ID_OUTROS_DESPESA, ID_OUTROS_RECEITA } from '../data/categoriasPadrao';
import { efeitoTransacao } from './contas';
import { dataValida } from './date';
import { novoId, proximoTempo } from './id';
import { parseValor } from './money';
import { DESCRICAO_MAX, normalizarTexto, validarTransacao } from './transacoes';
import {
  falha,
  ok,
  type AppState,
  type Centavos,
  type DataISO,
  type FormatoData,
  type Importacao,
  type MapeamentoCsv,
  type Resultado,
  type TipoMovimento,
  type Transacao,
} from './types';

export const TAMANHO_MAXIMO_BYTES = 5 * 1024 * 1024;
export const FORMATOS_DATA: FormatoData[] = ['dd/mm/aaaa', 'aaaa-mm-dd', 'dd-mm-aaaa'];

export function validarArquivo(nome: string, tamanho: number): Resultado<void> {
  if (!/\.csv$/i.test(nome)) return falha('Selecione um arquivo com extensão .csv.');
  if (tamanho > TAMANHO_MAXIMO_BYTES) return falha('O arquivo passa de 5 MB e não pode ser importado.');
  return ok(undefined);
}

/** Lê os bytes como UTF-8 e, se não forem válidos, como Windows-1252 (comum em bancos brasileiros). */
export function decodificar(bytes: Uint8Array): string {
  let texto: string;
  try {
    texto = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    texto = new TextDecoder('windows-1252').decode(bytes);
  }
  return texto.replace(/^﻿/, '');
}

export type Separador = ',' | ';';

/** Escolhe entre `,` e `;` pela primeira linha, ignorando o que estiver entre aspas. */
export function detectarSeparador(texto: string): Separador {
  let virgulas = 0;
  let pontoEVirgulas = 0;
  let dentro = false;
  for (const c of texto) {
    if (c === '"') dentro = !dentro;
    else if (!dentro && (c === '\n' || c === '\r')) break;
    else if (!dentro && c === ',') virgulas++;
    else if (!dentro && c === ';') pontoEVirgulas++;
  }
  return pontoEVirgulas > 0 && pontoEVirgulas >= virgulas ? ';' : ',';
}

/** Parser de CSV com campos entre aspas, aspas escapadas ("") e quebras de linha dentro de campo. */
export function parseCsv(texto: string, separador: Separador = detectarSeparador(texto)): string[][] {
  const linhas: string[][] = [];
  let linha: string[] = [];
  let campo = '';
  let dentro = false;
  let temConteudo = false;

  const fecharCampo = () => {
    linha.push(campo);
    campo = '';
  };
  const fecharLinha = () => {
    fecharCampo();
    if (temConteudo || linha.some((c) => c.trim() !== '')) linhas.push(linha);
    linha = [];
    temConteudo = false;
  };

  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (dentro) {
      if (c === '"') {
        if (texto[i + 1] === '"') {
          campo += '"';
          i++;
        } else dentro = false;
      } else campo += c;
    } else if (c === '"') {
      dentro = true;
      temConteudo = true;
    } else if (c === separador) {
      fecharCampo();
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && texto[i + 1] === '\n') i++;
      fecharLinha();
    } else campo += c;
  }
  if (campo !== '' || linha.length > 0 || temConteudo) fecharLinha();
  return linhas;
}

const padroesData: Record<FormatoData, RegExp> = {
  'dd/mm/aaaa': /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/,
  'aaaa-mm-dd': /^(\d{4})-(\d{1,2})-(\d{1,2})$/,
  'dd-mm-aaaa': /^(\d{1,2})-(\d{1,2})-(\d{4})$/,
};

/** Converte no formato escolhido; devolve null se o texto não bater com ele ou a data não existir. */
export function parseData(texto: string, formato: FormatoData): DataISO | null {
  const m = padroesData[formato].exec(texto.trim());
  if (!m) return null;
  const [ano, mes, dia] = formato === 'aaaa-mm-dd' ? [m[1], m[2], m[3]] : [m[3], m[2], m[1]];
  const iso = `${ano}-${mes.padStart(2, '0')}-${dia.padStart(2, '0')}`;
  return dataValida(iso) ? iso : null;
}

/** Primeiro formato em que todas as amostras não vazias são datas válidas. */
export function detectarFormatoData(amostras: string[]): FormatoData | null {
  const textos = amostras.map((a) => a.trim()).filter(Boolean);
  if (textos.length === 0) return null;
  return FORMATOS_DATA.find((f) => textos.every((t) => parseData(t, f) !== null)) ?? null;
}

/** Valor com sinal; parênteses indicam negativo (`(50,00)`). */
export function parseValorCsv(texto: string): Centavos | null {
  const limpo = texto.trim();
  const parenteses = /^\(.*\)$/.test(limpo);
  const valor = parseValor(parenteses ? limpo.slice(1, -1) : limpo);
  if (valor === null) return null;
  return parenteses ? -Math.abs(valor) : valor;
}

const cabecalhoContem = (cab: string, ...termos: string[]) => termos.some((t) => normalizarTexto(cab).includes(t));

/** Sugere o mapeamento a partir do cabeçalho e dos dados; o usuário pode ajustar. */
export function adivinharMapeamento(linhas: string[][]): MapeamentoCsv {
  const primeira = linhas[0] ?? [];
  const colunas = Math.max(...linhas.map((l) => l.length), 0);
  const achar = (...termos: string[]) => {
    const i = primeira.findIndex((c) => cabecalhoContem(c, ...termos));
    return i >= 0 ? i : null;
  };
  const colData = achar('data');
  const temCabecalho = colData !== null || achar('descri', 'historico', 'valor') !== null;
  const dados = temCabecalho ? linhas.slice(1) : linhas;
  const credito = achar('credito', 'entrada');
  const debito = achar('debito', 'saida');
  const valor = achar('valor', 'quantia');
  const usaDuasColunas = valor === null && credito !== null && debito !== null;
  const data = colData ?? 0;
  const descricao = achar('descri', 'historico', 'lancamento', 'estabelecimento') ?? Math.min(1, Math.max(colunas - 1, 0));
  const formatoData = detectarFormatoData(dados.map((l) => l[data] ?? '')) ?? 'dd/mm/aaaa';
  return {
    colData: data,
    colDescricao: descricao,
    colValor: usaDuasColunas ? null : (valor ?? Math.min(2, Math.max(colunas - 1, 0))),
    colCredito: usaDuasColunas ? credito : null,
    colDebito: usaDuasColunas ? debito : null,
    formatoData,
    temCabecalho,
  };
}

export interface LinhaInterpretada {
  /** Posição da linha no arquivo (começando em 1), para exibir ao usuário. */
  indice: number;
  data: DataISO | null;
  descricao: string;
  valor: Centavos;
  tipo: TipoMovimento;
  erro?: string;
}

export function interpretarLinhas(linhas: string[][], m: MapeamentoCsv): LinhaInterpretada[] {
  const resultado: LinhaInterpretada[] = [];
  linhas.forEach((celulas, posicao) => {
    if (m.temCabecalho && posicao === 0) return;
    const celula = (i: number | null) => (i === null ? '' : (celulas[i] ?? '').trim());
    const dataTexto = celula(m.colData);
    const data = dataTexto ? parseData(dataTexto, m.formatoData) : null;
    const descricao = celula(m.colDescricao).replace(/\s+/g, ' ').slice(0, DESCRICAO_MAX);
    const linha: LinhaInterpretada = { indice: posicao + 1, data, descricao, valor: 0, tipo: 'despesa' };

    let erroValor: string | undefined;
    if (m.colValor !== null) {
      const texto = celula(m.colValor);
      const v = texto === '' ? null : parseValorCsv(texto);
      if (texto === '') erroValor = 'Valor ausente';
      else if (v === null) erroValor = 'Valor inválido';
      else if (v === 0) erroValor = 'Valor zero';
      else {
        linha.tipo = v < 0 ? 'despesa' : 'receita';
        linha.valor = Math.abs(v);
      }
    } else {
      const deb = celula(m.colDebito) === '' ? 0 : parseValorCsv(celula(m.colDebito));
      const cred = celula(m.colCredito) === '' ? 0 : parseValorCsv(celula(m.colCredito));
      if (deb === null || cred === null) erroValor = 'Valor inválido';
      else if (deb !== 0 && cred !== 0) erroValor = 'Crédito e débito preenchidos na mesma linha';
      else if (deb === 0 && cred === 0) erroValor = 'Valor ausente';
      else if (deb !== 0) {
        linha.tipo = 'despesa';
        linha.valor = Math.abs(deb);
      } else {
        linha.tipo = 'receita';
        linha.valor = Math.abs(cred as number);
      }
    }

    if (!dataTexto) linha.erro = 'Data ausente';
    else if (!data) linha.erro = 'Data inválida para o formato escolhido';
    else if (erroValor) linha.erro = erroValor;
    resultado.push(linha);
  });
  return resultado;
}

const chaveDuplicata = (data: string, efeito: Centavos, descricao: string) => `${data}|${efeito}|${normalizarTexto(descricao)}`;

/** Mesma conta, mesma data, mesmo valor e mesma descrição normalizada. */
export function marcarDuplicatas(linhas: LinhaInterpretada[], estado: AppState, contaId: string): Set<number> {
  const existentes = new Set(estado.transacoes.filter((t) => t.contaId === contaId).map((t) => chaveDuplicata(t.data, efeitoTransacao(t), t.descricao)));
  const duplicadas = new Set<number>();
  for (const l of linhas) {
    if (l.erro || !l.data) continue;
    const efeito = l.tipo === 'receita' ? l.valor : -l.valor;
    if (existentes.has(chaveDuplicata(l.data, efeito, l.descricao))) duplicadas.add(l.indice);
  }
  return duplicadas;
}

/**
 * Reutiliza a categoria de uma transação anterior com a mesma descrição normalizada;
 * sem histórico, usa "Outros" do tipo correspondente.
 */
export function sugerirCategoria(estado: AppState, descricao: string, tipo: TipoMovimento): string | undefined {
  const ativas = new Map(estado.categorias.filter((c) => !c.arquivada && c.tipo === tipo).map((c) => [c.id, c]));
  const alvo = normalizarTexto(descricao);
  if (alvo) {
    let melhor: Transacao | undefined;
    for (const t of estado.transacoes) {
      if (t.tipo === tipo && ativas.has(t.categoriaId) && normalizarTexto(t.descricao) === alvo && (!melhor || t.criadaEm > melhor.criadaEm)) melhor = t;
    }
    if (melhor) return melhor.categoriaId;
  }
  const idOutros = tipo === 'despesa' ? ID_OUTROS_DESPESA : ID_OUTROS_RECEITA;
  if (ativas.has(idOutros)) return idOutros;
  const porNome = [...ativas.values()].find((c) => normalizarTexto(c.nome) === 'outros');
  return (porNome ?? [...ativas.values()][0])?.id;
}

export interface ItemImportacao {
  data: DataISO;
  descricao: string;
  valor: Centavos;
  tipo: TipoMovimento;
  categoriaId: string;
}

/** Grava todos os itens de uma vez ou nenhum: qualquer item inválido cancela a importação inteira. */
export function importarTransacoes(
  estado: AppState,
  contaId: string,
  itens: ItemImportacao[],
  mapeamento: MapeamentoCsv,
  hoje: DataISO,
): Resultado<{ estado: AppState; importacao: Importacao }> {
  if (itens.length === 0) return falha('Nenhuma linha selecionada para importar.');
  const importacaoId = novoId();
  const novas: Transacao[] = [];
  for (const item of itens) {
    const v = validarTransacao(estado, { contaId, ...item });
    if (!v.ok) return falha(`Linha de ${item.data} ("${item.descricao}"): ${v.erro}`);
    novas.push({ ...v.valor, id: novoId(), criadaEm: proximoTempo(), importacaoId });
  }
  const importacao: Importacao = { id: importacaoId, data: hoje, contaId, transacaoIds: novas.map((t) => t.id) };
  return ok({
    importacao,
    estado: {
      ...estado,
      transacoes: [...estado.transacoes, ...novas],
      importacoes: [...estado.importacoes, importacao],
      mapeamentosCsv: { ...estado.mapeamentosCsv, [contaId]: mapeamento },
    },
  });
}

/** Remove exatamente as transações criadas pela importação. */
export function desfazerImportacao(estado: AppState, importacaoId: string): Resultado<AppState> {
  const importacao = estado.importacoes.find((i) => i.id === importacaoId);
  if (!importacao) return falha('Importação não encontrada.');
  const ids = new Set(importacao.transacaoIds);
  return ok({
    ...estado,
    transacoes: estado.transacoes.filter((t) => !ids.has(t.id)),
    importacoes: estado.importacoes.filter((i) => i.id !== importacaoId),
  });
}
export type Centavos = number;
/** Data no formato AAAA-MM-DD. */
export type DataISO = string;
/** Mês no formato AAAA-MM. */
export type Mes = string;

export type TipoConta = 'corrente' | 'poupanca' | 'dinheiro' | 'cartao' | 'investimento';
export type TipoMovimento = 'receita' | 'despesa';

/** Ciclo e limite de um cartão de crédito. Dias de 1 a 28 para valerem em todos os meses. */
export interface CartaoConfig {
  diaFechamento: number;
  diaVencimento: number;
  limite: Centavos;
}

export interface Conta {
  id: string;
  nome: string;
  tipo: TipoConta;
  saldoInicial: Centavos;
  arquivada: boolean;
  criadaEm: number;
  /** Só para contas do tipo cartão. */
  cartao?: CartaoConfig;
}

export interface Categoria {
  id: string;
  nome: string;
  tipo: TipoMovimento;
  arquivada: boolean;
}

export interface Transacao {
  id: string;
  contaId: string;
  categoriaId: string;
  tipo: TipoMovimento;
  /** Sempre positivo; o sinal vem do tipo. */
  valor: Centavos;
  data: DataISO;
  descricao: string;
  criadaEm: number;
  importacaoId?: string;
  /** Presente em compras parceladas; as parcelas de uma compra compartilham o grupoId. */
  parcela?: { grupoId: string; numero: number; total: number };
}

export interface Orcamento {
  categoriaId: string;
  mes: Mes;
  limite: Centavos;
}

export interface Aporte {
  id: string;
  data: DataISO;
  /** Positivo para aporte, negativo para retirada. */
  valor: Centavos;
}

export type StatusMeta = 'ativa' | 'concluida' | 'arquivada';

export interface Meta {
  id: string;
  nome: string;
  valorAlvo: Centavos;
  prazo?: DataISO;
  aportes: Aporte[];
  status: StatusMeta;
  concluidaEm?: DataISO;
  criadaEm: number;
}

/** Valor mensal fixo considerado na projeção; não gera transações. */
export interface Recorrencia {
  id: string;
  descricao: string;
  tipo: TipoMovimento;
  valor: Centavos;
  categoriaId: string;
  ativa: boolean;
}

export type FormatoData = 'dd/mm/aaaa' | 'aaaa-mm-dd' | 'dd-mm-aaaa';

export interface MapeamentoCsv {
  colData: number;
  colDescricao: number;
  /** Coluna única com sinal. */
  colValor: number | null;
  colCredito: number | null;
  colDebito: number | null;
  formatoData: FormatoData;
  temCabecalho: boolean;
}

export interface Importacao {
  id: string;
  data: DataISO;
  contaId: string;
  transacaoIds: string[];
}

/** Pagamento de fatura: movimenta dinheiro entre contas e não é receita nem despesa. */
export interface PagamentoFatura {
  id: string;
  contaCartaoId: string;
  /** Mês de fechamento da fatura (AAAA-MM). */
  mesFatura: Mes;
  valor: Centavos;
  data: DataISO;
  contaOrigemId: string;
}

export interface AppState {
  schemaVersion: number;
  contas: Conta[];
  categorias: Categoria[];
  transacoes: Transacao[];
  orcamentos: Orcamento[];
  metas: Meta[];
  recorrencias: Recorrencia[];
  mapeamentosCsv: Record<string, MapeamentoCsv>;
  importacoes: Importacao[];
  pagamentosFatura: PagamentoFatura[];
}

export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };

export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });

import { categoriasPadrao } from '../data/categoriasPadrao';
import { falha, ok, type AppState, type Resultado } from '../domain/types';

/** Toda chave escrita pelo app começa com este prefixo. */
export const PREFIXO = 'financas:';
export const CHAVE_ESTADO = `${PREFIXO}estado`;
export const SCHEMA_ATUAL = 2;

export function estadoInicial(): AppState {
  return {
    schemaVersion: SCHEMA_ATUAL,
    contas: [],
    categorias: categoriasPadrao(),
    transacoes: [],
    orcamentos: [],
    metas: [],
    recorrencias: [],
    mapeamentosCsv: {},
    importacoes: [],
    pagamentosFatura: [],
  };
}

export type Carga =
  | { tipo: 'ok'; estado: AppState }
  | { tipo: 'corrompido'; bruto: string }
  | { tipo: 'versao-futura'; bruto: string; versao: number };

type Dados = Record<string, unknown>;

/** Migrações indexadas pela versão de origem: `migracoes[n]` leva de n para n+1. */
const migracoes: Record<number, (dados: Dados) => Dados> = {
  0: (dados) => ({
    ...dados,
    schemaVersion: 1,
    contas: dados.contas ?? [],
    categorias: dados.categorias ?? categoriasPadrao(),
    transacoes: dados.transacoes ?? [],
    orcamentos: dados.orcamentos ?? [],
    metas: dados.metas ?? [],
    recorrencias: dados.recorrencias ?? [],
    mapeamentosCsv: dados.mapeamentosCsv ?? {},
    importacoes: dados.importacoes ?? [],
  }),
  // v2: pagamentos de fatura de cartão.
  1: (dados) => ({ ...dados, schemaVersion: 2, pagamentosFatura: dados.pagamentosFatura ?? [] }),
};

const CHAVES_LISTA = ['contas', 'categorias', 'transacoes', 'orcamentos', 'metas', 'recorrencias', 'importacoes', 'pagamentosFatura'] as const;

function ehObjeto(x: unknown): x is Dados {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

function estruturaValida(dados: Dados): boolean {
  return (
    CHAVES_LISTA.every((k) => Array.isArray(dados[k])) &&
    ehObjeto(dados.mapeamentosCsv) &&
    dados.schemaVersion === SCHEMA_ATUAL
  );
}

/** Migra um objeto qualquer até a versão atual. Versões futuras são recusadas. */
export function migrar(bruto: unknown): { tipo: 'ok'; estado: AppState } | { tipo: 'corrompido' } | { tipo: 'versao-futura'; versao: number } {
  if (!ehObjeto(bruto)) return { tipo: 'corrompido' };
  let dados: Dados = bruto;
  const versaoLida = dados.schemaVersion === undefined ? 0 : dados.schemaVersion;
  if (typeof versaoLida !== 'number' || !Number.isInteger(versaoLida) || versaoLida < 0) {
    return { tipo: 'corrompido' };
  }
  if (versaoLida > SCHEMA_ATUAL) return { tipo: 'versao-futura', versao: versaoLida };
  if (versaoLida === 0 && !CHAVES_LISTA.some((k) => k in dados)) return { tipo: 'corrompido' };
  for (let v = versaoLida; v < SCHEMA_ATUAL; v++) {
    const migracao = migracoes[v];
    if (!migracao) return { tipo: 'corrompido' };
    dados = migracao(dados);
  }
  // Chaves aditivas (novos módulos) ausentes em dados antigos recebem o valor inicial, sem migração.
  const padrao = estadoInicial() as unknown as Dados;
  for (const chave of Object.keys(padrao)) if (dados[chave] === undefined) dados = { ...dados, [chave]: padrao[chave] };
  if (!estruturaValida(dados)) return { tipo: 'corrompido' };
  return { tipo: 'ok', estado: dados as unknown as AppState };
}

export function carregar(storage: Storage): Carga {
  let bruto: string | null;
  try {
    bruto = storage.getItem(CHAVE_ESTADO);
  } catch {
    return { tipo: 'ok', estado: estadoInicial() };
  }
  if (bruto === null) return { tipo: 'ok', estado: estadoInicial() };
  let parsed: unknown;
  try {
    parsed = JSON.parse(bruto);
  } catch {
    return { tipo: 'corrompido', bruto };
  }
  const r = migrar(parsed);
  if (r.tipo === 'ok') return r;
  if (r.tipo === 'versao-futura') return { tipo: 'versao-futura', bruto, versao: r.versao };
  return { tipo: 'corrompido', bruto };
}

/** Lança se o navegador recusar a gravação (cota excedida, armazenamento bloqueado). */
export function salvar(estado: AppState, storage: Storage): void {
  storage.setItem(CHAVE_ESTADO, JSON.stringify(estado));
}

export function apagarTudo(storage: Storage): void {
  const chaves: string[] = [];
  for (let i = 0; i < storage.length; i++) {
    const chave = storage.key(i);
    if (chave?.startsWith(PREFIXO)) chaves.push(chave);
  }
  chaves.forEach((c) => storage.removeItem(c));
}

export function exportarJson(estado: AppState): string {
  return JSON.stringify(estado, null, 2);
}

/** Lê um arquivo de exportação, migrando se necessário. */
export function importarJson(texto: string): Resultado<AppState> {
  let parsed: unknown;
  try {
    parsed = JSON.parse(texto);
  } catch {
    return falha('O arquivo não é um JSON válido.');
  }
  const r = migrar(parsed);
  if (r.tipo === 'ok') return ok(r.estado);
  if (r.tipo === 'versao-futura') {
    return falha(`O arquivo foi gerado por uma versão mais nova do app (esquema ${r.versao}).`);
  }
  return falha('O arquivo não parece ser uma exportação deste app.');
}
