  const [filtros, setFiltros] = useState<FiltrosTransacoes>(filtrosPadrao);
  const [limite, setLimite] = useState(TAMANHO_PAGINA);
  const [criando, setCriando] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [excluindo, setExcluindo] = useState<Transacao | null>(null);
  const [removida, setRemovida] = useState<Transacao | null>(null);
  const [erro, setErro] = useState<string | null>(null);

  useEffect(() => {
    if (!removida) return;
    const timer = setTimeout(() => setRemovida(null), TEMPO_DESFAZER_MS);
    return () => clearTimeout(timer);
  }, [removida]);

  const filtradas = useMemo(() => ordenarTransacoes(filtrarTransacoes(estado.transacoes, filtros)), [estado.transacoes, filtros]);
  const totais = useMemo(() => totaisTransacoes(filtradas), [filtradas]);
  const nomeConta = useMemo(() => new Map(estado.contas.map((c) => [c.id, c.nome])), [estado.contas]);
  const categoria = useMemo(() => new Map(estado.categorias.map((c) => [c.id, c])), [estado.categorias]);
  const visiveis = filtradas.slice(0, limite);

  const mudarFiltros = (f: FiltrosTransacoes) => {
    setFiltros(f);
    setLimite(TAMANHO_PAGINA);
  };

  const desfazer = () => {
    if (!removida) return;
    const r = store.aplicar((s) => restaurarTransacao(s, removida));
    setErro(r.ok ? null : r.erro);
    setRemovida(null);
  };

  const abaClasse = (a: Aba) =>
    `rounded-t-md px-4 py-2 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-emerald-600 ${
      aba === a ? 'border-b-2 border-emerald-700 text-emerald-900' : 'text-slate-600 hover:text-slate-900'
    }`;

  return (
    <div>
      <TituloPagina
        acoes={aba === 'transacoes' && !criando ? <Botao onClick={() => { setCriando(true); setEditandoId(null); }}>Nova transação</Botao> : undefined}
      >
        Transações
      </TituloPagina>

      <div role="tablist" aria-label="Seções" className="mb-4 flex gap-1 border-b border-slate-200">
        <button role="tab" type="button" id="aba-transacoes" aria-selected={aba === 'transacoes'} aria-controls="painel-transacoes" className={abaClasse('transacoes')} onClick={() => setAba('transacoes')}>
          Transações
        </button>
        <button role="tab" type="button" id="aba-categorias" aria-selected={aba === 'categorias'} aria-controls="painel-categorias" className={abaClasse('categorias')} onClick={() => setAba('categorias')}>
          Categorias
        </button>
      </div>

      {aba === 'categorias' ? (
        <div role="tabpanel" id="painel-categorias" aria-labelledby="aba-categorias">
          <CategoriasPanel />
        </div>
      ) : (
        <div role="tabpanel" id="painel-transacoes" aria-labelledby="aba-transacoes" className="space-y-4">
          {erro ? <Alerta>{erro}</Alerta> : null}
          {removida ? (
            <Alerta tipo="aviso">
              <span className="flex flex-wrap items-center justify-between gap-2">
                Transação excluída.
                <Botao variante="secundario" onClick={desfazer}>
                  Desfazer
                </Botao>
              </span>
            </Alerta>
          ) : null}

          {criando ? (
            <Cartao titulo="Nova transação">
              <TransacaoForm
                estado={estado}
                onCancelar={() => setCriando(false)}
                onSalvar={(dados) => {
                  const r = store.aplicar((s) => criarTransacao(s, dados));
                  if (r.ok) setCriando(false);
                  return r;
                }}
              />
            </Cartao>
          ) : null}

          <Cartao titulo="Filtros">
            <FiltrosTransacoesForm estado={estado} filtros={filtros} onChange={mudarFiltros} onLimpar={() => mudarFiltros(filtrosPadrao())} />
          </Cartao>

          <div className="grid gap-3 sm:grid-cols-3" aria-label="Totais do filtro" role="group">
            <Cartao>
              <p className="text-sm text-slate-600">Receitas</p>
              <p className="text-xl font-bold" data-testid="total-receitas">{formatarMoeda(totais.receitas)}</p>
            </Cartao>
            <Cartao>
              <p className="text-sm text-slate-600">Despesas</p>
              <p className="text-xl font-bold" data-testid="total-despesas">{formatarMoeda(totais.despesas)}</p>
            </Cartao>
            <Cartao>
              <p className="text-sm text-slate-600">Resultado</p>
              <p className="text-xl font-bold" data-testid="total-resultado">
                <Valor centavos={totais.resultado} texto={formatarMoeda(totais.resultado)} />
              </p>
            </Cartao>
          </div>

          {estado.transacoes.length === 0 ? (
            <EstadoVazio
              titulo="Nenhuma transação registrada"
              acao={!criando ? <Botao onClick={() => setCriando(true)}>Adicione sua primeira transação</Botao> : undefined}
            >
              Registre receitas e despesas para acompanhar seu dinheiro.
            </EstadoVazio>
          ) : filtradas.length === 0 ? (
            <EstadoVazio titulo="Nenhuma transação encontrada">Ajuste ou limpe os filtros para ver mais resultados.</EstadoVazio>
          ) : (
            <Cartao>
              <p className="mb-2 text-sm text-slate-600" aria-live="polite">
                {filtradas.length} {filtradas.length === 1 ? 'transação' : 'transações'}
              </p>
              <ul className="divide-y divide-slate-200" aria-label="Lista de transações">
                {visiveis.map((t) => {
                  if (editandoId === t.id) {
                    return (
                      <li key={t.id} className="py-3">
                        <TransacaoForm
                          estado={estado}
                          inicial={t}
                          onCancelar={() => setEditandoId(null)}
                          onSalvar={(dados) => {
                            const r = store.aplicar((s) => editarTransacao(s, t.id, dados));
                            if (r.ok) setEditandoId(null);
                            return r;
                          }}
                        />
                      </li>
                    );
                  }
                  const cat = categoria.get(t.categoriaId);
                  const efeito = efeitoTransacao(t);
                  const rotulo = t.descricao || cat?.nome || 'Sem descrição';
                  return (
                    <li key={t.id} className="flex flex-wrap items-center justify-between gap-2 py-3">
                      <div className="min-w-0 flex-1">
                        <p className="truncate font-medium text-slate-900">{rotulo}</p>
                        <p className="text-xs text-slate-600">
                          {formatarData(t.data)} · {cat?.nome ?? 'Sem categoria'}
                          {cat?.arquivada ? ' (arquivada)' : ''} · {nomeConta.get(t.contaId) ?? 'Conta removida'}
                        </p>
                      </div>
                      <div className="flex flex-wrap items-center gap-2">
                        <Valor centavos={efeito} texto={`${efeito > 0 ? '+' : ''}${formatarMoeda(efeito)}`} />
                        <Botao variante="secundario" aria-label={`Editar ${rotulo}`} onClick={() => { setEditandoId(t.id); setCriando(false); }}>
                          Editar
                        </Botao>
                        <Botao variante="perigo" aria-label={`Excluir ${rotulo}`} onClick={() => setExcluindo(t)}>
                          Excluir
                        </Botao>
                      </div>
                    </li>
                  );
                })}
              </ul>
              {filtradas.length > visiveis.length ? (
                <div className="mt-3 flex justify-center">
                  <Botao variante="secundario" onClick={() => setLimite((l) => l + TAMANHO_PAGINA)}>
                    Mostrar mais ({filtradas.length - visiveis.length} restantes)
                  </Botao>
                </div>
              ) : null}
            </Cartao>
          )}
        </div>
      )}

      {excluindo?.parcela ? (
        <ExclusaoParcelaDialog
          transacao={excluindo}
          onCancelar={() => setExcluindo(null)}
          onEscolher={(escopo) => {
            const alvo = excluindo;
            const r = store.aplicar((s) => excluirParcela(s, alvo.id, escopo));
            if (r.ok) {
              setRemovida(escopo === 'uma' ? alvo : null);
              setErro(null);
            } else setErro(r.erro);
            setExcluindo(null);
          }}
        />
      ) : null}
      {excluindo && !excluindo.parcela ? (
        <ConfirmDialog
          titulo="Excluir transação?"
          mensagem={`Excluir "${excluindo.descricao || 'transação'}" de ${formatarData(excluindo.data)}? Você poderá desfazer por alguns segundos.`}
          rotuloConfirmar="Excluir"
          perigo
          onCancelar={() => setExcluindo(null)}
          onConfirmar={() => {
            const alvo = excluindo;
            const r = store.aplicar((s) => excluirTransacao(s, alvo.id));
            if (r.ok) {
              setRemovida(alvo);
              setErro(null);
            } else setErro(r.erro);
            setExcluindo(null);
          }}
        />
      ) : null}
    </div>
  );
}
import { efeitoTransacao } from './contas';
import { dataValida } from './date';
import { novoId, proximoTempo } from './id';
import {
  falha,
  ok,
  type AppState,
  type Categoria,
  type Centavos,
  type DataISO,
  type Resultado,
  type TipoMovimento,
  type Transacao,
} from './types';

export const DESCRICAO_MAX = 100;
export const CATEGORIA_NOME_MAX = 30;

export interface DadosTransacao {
  contaId: string;
  categoriaId: string;
  tipo: TipoMovimento;
  valor: Centavos;
  data: DataISO;
  descricao: string;
}

export function validarTransacao(estado: AppState, dados: DadosTransacao, existente?: Transacao): Resultado<DadosTransacao> {
  const conta = estado.contas.find((c) => c.id === dados.contaId);
  if (!conta) return falha('Selecione uma conta.', 'contaId');
  if (conta.arquivada && existente?.contaId !== conta.id) return falha('Esta conta está arquivada.', 'contaId');
  if (!Number.isInteger(dados.valor) || dados.valor <= 0) return falha('O valor deve ser maior que zero.', 'valor');
  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
  const categoria = estado.categorias.find((c) => c.id === dados.categoriaId);
  if (!categoria) return falha('Selecione uma categoria.', 'categoriaId');
  if (categoria.tipo !== dados.tipo) return falha(`A categoria deve ser de ${dados.tipo}.`, 'categoriaId');
  if (categoria.arquivada && existente?.categoriaId !== categoria.id) return falha('Esta categoria está arquivada.', 'categoriaId');
  const descricao = dados.descricao.trim();
  if (descricao.length > DESCRICAO_MAX) return falha(`A descrição deve ter no máximo ${DESCRICAO_MAX} caracteres.`, 'descricao');
  return ok({ ...dados, descricao });
}

export function criarTransacao(estado: AppState, dados: DadosTransacao): Resultado<AppState> {
  const v = validarTransacao(estado, dados);
  if (!v.ok) return v;
  const transacao: Transacao = { ...v.valor, id: novoId(), criadaEm: proximoTempo() };
  return ok({ ...estado, transacoes: [...estado.transacoes, transacao] });
}

export function editarTransacao(estado: AppState, id: string, dados: DadosTransacao): Resultado<AppState> {
  const atual = estado.transacoes.find((t) => t.id === id);
  if (!atual) return falha('Transação não encontrada.');
  const v = validarTransacao(estado, dados, atual);
  if (!v.ok) return v;
  return ok({ ...estado, transacoes: estado.transacoes.map((t) => (t.id === id ? { ...t, ...v.valor } : t)) });
}

export function excluirTransacao(estado: AppState, id: string): Resultado<AppState> {
  if (!estado.transacoes.some((t) => t.id === id)) return falha('Transação não encontrada.');
  return ok({ ...estado, transacoes: estado.transacoes.filter((t) => t.id !== id) });
}

/** Desfaz uma exclusão, devolvendo a transação exatamente como era. */
export function restaurarTransacao(estado: AppState, transacao: Transacao): Resultado<AppState> {
  if (estado.transacoes.some((t) => t.id === transacao.id)) return ok(estado);
  if (!estado.contas.some((c) => c.id === transacao.contaId) || !estado.categorias.some((c) => c.id === transacao.categoriaId)) {
    return falha('A conta ou a categoria desta transação não existe mais.');
  }
  return ok({ ...estado, transacoes: [...estado.transacoes, transacao] });
}

export interface FiltrosTransacoes {
  de?: DataISO;
  ate?: DataISO;
  contaId?: string;
  categoriaId?: string;
  tipo?: TipoMovimento;
  texto?: string;
}

export function normalizarTexto(texto: string): string {
  return texto
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLocaleLowerCase('pt-BR')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Aplica todos os filtros presentes (E lógico). */
export function filtrarTransacoes(transacoes: Transacao[], f: FiltrosTransacoes): Transacao[] {
  const texto = f.texto ? normalizarTexto(f.texto) : '';
  return transacoes.filter(
    (t) =>
      (!f.de || t.data >= f.de) &&
      (!f.ate || t.data <= f.ate) &&
      (!f.contaId || t.contaId === f.contaId) &&
      (!f.categoriaId || t.categoriaId === f.categoriaId) &&
      (!f.tipo || t.tipo === f.tipo) &&
      (!texto || normalizarTexto(t.descricao).includes(texto)),
  );
}

/** Data decrescente; em empate, a criada mais recentemente primeiro. */
export function ordenarTransacoes(transacoes: Transacao[]): Transacao[] {
  return [...transacoes].sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : b.criadaEm - a.criadaEm));
}

export interface TotaisTransacoes {
  receitas: Centavos;
  despesas: Centavos;
  resultado: Centavos;
}

export function totaisTransacoes(transacoes: Transacao[]): TotaisTransacoes {
  let receitas = 0;
  let despesas = 0;
  for (const t of transacoes) {
    if (t.tipo === 'receita') receitas += t.valor;
    else despesas += t.valor;
  }
  return { receitas, despesas, resultado: receitas - despesas };
}

export { efeitoTransacao };

// ---------------------------------------------------------------- categorias

export interface DadosCategoria {
  nome: string;
  tipo: TipoMovimento;
}

export function validarNomeCategoria(categorias: Categoria[], nome: string, tipo: TipoMovimento, ignorarId?: string): Resultado<string> {
  const limpo = nome.trim();
  if (!limpo) return falha('Informe o nome da categoria.', 'nome');
  if (limpo.length > CATEGORIA_NOME_MAX) return falha(`O nome deve ter no máximo ${CATEGORIA_NOME_MAX} caracteres.`, 'nome');
  const igual = (n: string) => n.trim().toLocaleLowerCase('pt-BR') === limpo.toLocaleLowerCase('pt-BR');
  if (categorias.some((c) => c.tipo === tipo && c.id !== ignorarId && igual(c.nome))) {
    return falha('Já existe uma categoria com esse nome neste tipo.', 'nome');
  }
  return ok(limpo);
}

export function criarCategoria(estado: AppState, dados: DadosCategoria): Resultado<AppState> {
  const nome = validarNomeCategoria(estado.categorias, dados.nome, dados.tipo);
  if (!nome.ok) return nome;
  const categoria: Categoria = { id: novoId(), nome: nome.valor, tipo: dados.tipo, arquivada: false };
  return ok({ ...estado, categorias: [...estado.categorias, categoria] });
}

export function renomearCategoria(estado: AppState, id: string, nomeNovo: string): Resultado<AppState> {
  const categoria = estado.categorias.find((c) => c.id === id);
  if (!categoria) return falha('Categoria não encontrada.');
  const nome = validarNomeCategoria(estado.categorias, nomeNovo, categoria.tipo, id);
  if (!nome.ok) return nome;
  return ok({ ...estado, categorias: estado.categorias.map((c) => (c.id === id ? { ...c, nome: nome.valor } : c)) });
}

export function arquivarCategoria(estado: AppState, id: string, arquivada = true): Resultado<AppState> {
  if (!estado.categorias.some((c) => c.id === id)) return falha('Categoria não encontrada.');
  return ok({ ...estado, categorias: estado.categorias.map((c) => (c.id === id ? { ...c, arquivada } : c)) });
}

export function categoriaEmUso(estado: AppState, id: string): boolean {
  return estado.transacoes.some((t) => t.categoriaId === id) || estado.recorrencias.some((r) => r.categoriaId === id);
}

/**
 * Exclui a categoria. Se estiver em uso, exige uma categoria de destino do mesmo tipo
 * e reatribui transações e recorrências, de modo que nenhuma fique sem categoria.
 * Os limites de orçamento da categoria excluída são removidos.
 */
export function excluirCategoria(estado: AppState, id: string, destinoId?: string): Resultado<AppState> {
  const categoria = estado.categorias.find((c) => c.id === id);
  if (!categoria) return falha('Categoria não encontrada.');
  let transacoes = estado.transacoes;
  let recorrencias = estado.recorrencias;
  if (categoriaEmUso(estado, id)) {
    if (!destinoId) return falha('Esta categoria está em uso. Escolha uma categoria de destino ou arquive-a.', 'destino');
    const destino = estado.categorias.find((c) => c.id === destinoId);
    if (!destino || destino.id === id || destino.tipo !== categoria.tipo || destino.arquivada) {
      return falha('Escolha uma categoria de destino ativa do mesmo tipo.', 'destino');
    }
    transacoes = transacoes.map((t) => (t.categoriaId === id ? { ...t, categoriaId: destinoId } : t));
    recorrencias = recorrencias.map((r) => (r.categoriaId === id ? { ...r, categoriaId: destinoId } : r));
  }
  return ok({
    ...estado,
    categorias: estado.categorias.filter((c) => c.id !== id),
    orcamentos: estado.orcamentos.filter((o) => o.categoriaId !== id),
    transacoes,
    recorrencias,
  });
}

  const [selecao, setSelecao] = useState<Record<number, boolean>>({});
  const [categoriasEscolhidas, setCategoriasEscolhidas] = useState<Record<number, string>>({});
  const [erro, setErro] = useState<string | null>(null);
  const [resumo, setResumo] = useState<Resumo | null>(null);
  const [arrastando, setArrastando] = useState(false);
  const entrada = useRef<HTMLInputElement>(null);

  const ultimaImportacao = estado.importacoes[estado.importacoes.length - 1];

  const reiniciar = () => {
    setNomeArquivo(null);
    setLinhasCsv(null);
    setMapeamento(null);
    setSelecao({});
    setCategoriasEscolhidas({});
  };

  const carregarArquivo = async (arquivo: File | undefined) => {
    if (!arquivo) return;
    setErro(null);
    setResumo(null);
    const valido = validarArquivo(arquivo.name, arquivo.size);
    if (!valido.ok) {
      reiniciar();
      setErro(valido.erro);
      return;
    }
    try {
      const texto = decodificar(new Uint8Array(await lerArquivoBuffer(arquivo)));
      const linhas = parseCsv(texto, detectarSeparador(texto));
      if (linhas.length === 0) {
        reiniciar();
        setErro('O arquivo está vazio.');
        return;
      }
      const lembrado = estado.mapeamentosCsv[contaEfetiva];
      const colunas = Math.max(...linhas.map((l) => l.length));
      const aproveitavel = lembrado && [lembrado.colData, lembrado.colDescricao, lembrado.colValor, lembrado.colCredito, lembrado.colDebito].every((c) => c === null || c < colunas);
      setLinhasCsv(linhas);
      setMapeamento(aproveitavel ? lembrado : adivinharMapeamento(linhas));
      setNomeArquivo(arquivo.name);
      setSelecao({});
      setCategoriasEscolhidas({});
    } catch (e) {
      reiniciar();
      setErro(e instanceof Error ? e.message : 'Não foi possível ler o arquivo.');
    }
  };

  const linhas: LinhaPrevia[] = useMemo(() => {
    if (!linhasCsv || !mapeamento) return [];
    const interpretadas = interpretarLinhas(linhasCsv, mapeamento);
    const duplicadas = marcarDuplicatas(interpretadas, estado, contaEfetiva);
    return interpretadas.map((l) => {
      const duplicata = duplicadas.has(l.indice);
      return {
        ...l,
        duplicata,
        selecionada: l.erro ? false : (selecao[l.indice] ?? !duplicata),
        categoriaId: l.erro ? undefined : (categoriasEscolhidas[l.indice] ?? sugerirCategoria(estado, l.descricao, l.tipo)),
      };
    });
  }, [linhasCsv, mapeamento, estado, contaEfetiva, selecao, categoriasEscolhidas]);

  const aImportar = linhas.filter((l) => l.selecionada);
  const comErro = linhas.filter((l) => l.erro).length;
  const ignoradas = linhas.length - aImportar.length - comErro;

  const confirmar = () => {
    if (!mapeamento) return;
    const itens = aImportar.map((l) => ({ data: l.data!, descricao: l.descricao, valor: l.valor, tipo: l.tipo, categoriaId: l.categoriaId ?? '' }));
    let criada = '';
    const r = store.aplicar((s) => {
      const imp = importarTransacoes(s, contaEfetiva, itens, mapeamento, hojeISO());
      if (!imp.ok) return imp;
      criada = imp.valor.importacao.id;
      return { ok: true, valor: imp.valor.estado };
    });
    if (!r.ok) {
      setErro(r.erro);
      return;
    }
    setErro(null);
    setResumo({ importacaoId: criada, importadas: itens.length, ignoradas, comErro });
    reiniciar();
  };

  const desfazer = (id: string) => {
    const r = store.aplicar((s) => desfazerImportacao(s, id));
    if (!r.ok) return setErro(r.erro);
    setErro(null);
    setResumo(null);
  };

  const soltar = (e: DragEvent) => {
    e.preventDefault();
    setArrastando(false);
    void carregarArquivo(e.dataTransfer.files[0]);
  };

  return (
    <div>
      <TituloPagina>Importar CSV</TituloPagina>
      <div className="space-y-4">
        {erro ? <Alerta>{erro}</Alerta> : null}

        {resumo ? (
          <Alerta tipo="sucesso">
            <span className="flex flex-wrap items-center justify-between gap-2">
              <span data-testid="resumo">
                Importação concluída: {resumo.importadas} importadas, {resumo.ignoradas} ignoradas, {resumo.comErro} com erro.
              </span>
              <Botao variante="secundario" onClick={() => desfazer(resumo.importacaoId)}>
                Desfazer importação
              </Botao>
            </span>
          </Alerta>
        ) : null}

